import { optionalRouter } from './router';

/**
 * Router-aware variant of the interactivity marker.
 *
 * When `expo-router` is available, this returns a `markInteractive` function
 * that automatically tags each metric with the current route's `pathname` and
 * skips reporting while the current screen is not focused. When the router is
 * not installed, it returns `null` so callers can fall back to the plain
 * `AppMetrics.markInteractive`.
 */
export function useObserveForRouter():
  | ((options?: Record<string, unknown>) => Promise<void> | void)
  | null {
  if (!optionalRouter) {
    return null;
  }

  optionalRouter.useRoute();
  const navigation = optionalRouter.useNavigation();
  const routeInfo = optionalRouter.useCurrentRouteInfo();

  return (options: Record<string, unknown> = {}) => {
    if (!navigation.isFocused()) {
      return;
    }
    return AppMetrics.markInteractive({ ...options, routeName: routeInfo.pathname });
  };
}
