import { requireNativeModule } from 'expo';

import { initRouterIntegration } from './integrations/expo-router/init';
import { isRouterInstalled } from './integrations/expo-router/router';
import type { Config, ExpoObserveModuleType } from './types';

const nativeModule = requireNativeModule<ExpoObserveModuleType>('ExpoObserve');

type ConfigureOptions = Config & { disableRouterIntegration?: boolean };

const handlers = {
  configure({ disableRouterIntegration, ...config }: ConfigureOptions) {
    nativeModule.configure(config);

    if (isRouterInstalled && !disableRouterIntegration) {
      initRouterIntegration();
    }
  },
  dispatchEvents() {
    return nativeModule.dispatchEvents();
  },
  setBundleDefaults(defaults: { environment: string; isJsDev: boolean }) {
    nativeModule.setBundleDefaults(defaults);
  },
};

export default new Proxy(nativeModule, {
  get(target, prop, receiver) {
    if (Object.prototype.hasOwnProperty.call(handlers, prop)) {
      return handlers[prop as keyof typeof handlers];
    }
    return Reflect.get(target, prop, receiver);
  },
});
