/**
 * The subset of the `expo-router` API that the observe integration depends on.
 *
 * `useCurrentRouteInfo` yields the current route info (notably its `pathname`),
 * which is attached to interactivity metrics as the `routeName`.
 */
export type OptionalRouter = {
  useRoute: () => unknown;
  useNavigation: () => { isFocused(): boolean };
  useCurrentRouteInfo: () => { pathname: string };
};

let isRouterInstalled = false;
let optionalRouter: OptionalRouter | undefined;

try {
  // `expo-router` is an optional peer of this package — apps that don't use it
  // should still be able to import and configure observability.
  const router = require('expo-router');
  optionalRouter = {
    useRoute: router.useRoute,
    useNavigation: router.useNavigation,
    useCurrentRouteInfo: () => ({ pathname: router.usePathname() }),
  };
  isRouterInstalled = true;
} catch {
  isRouterInstalled = false;
  optionalRouter = undefined;
}

export { isRouterInstalled, optionalRouter };
