let initialized = false;

/**
 * Whether {@link initRouterIntegration} has already run.
 */
export function isInitialized(): boolean {
  return initialized;
}

/**
 * Subscribes the router integration to navigation events and returns a function
 * that tears the subscription back down.
 */
export function initListeners(): () => void {
  return () => {};
}

/**
 * Wires up the expo-router integration exactly once. Repeated calls are no-ops
 * so that a second `configure` doesn't register duplicate listeners.
 */
export function initRouterIntegration(): void {
  if (initialized) {
    return;
  }
  initialized = true;
  initListeners();
}
